INSERT INTO "Tool" ("id","serverId","name","description","category","inputSchema","outputSchema","handlerConfig","fmLayout","fmScript","fmMethod","isEnabled","version","isAiGenerated","testConfig","sortOrder","createdAt","updatedAt") VALUES ('cmpezj4rx000bv0qdwmapvdzb','cmpe78bpf0000l704aera9ers','update_activity_entry','Update an existing time entry in the Activity Report. Use this to correct logged hours, change the category, fix the date, or update billing information on a specific activity record.','write','{"type":"object","properties":{"recordId":{"type":"string","description":"The FileMaker record ID of the activity entry to update"},"hours":{"type":"number","description":"Corrected number of hours"},"category":{"type":"string","description":"Updated category for the activity"},"date":{"type":"string","description":"Corrected date of the activity"},"ticketType":{"type":"string","description":"Updated ticket type"},"nonbillableTime":{"type":"number","description":"Updated non-billable hours amount"}},"required":["recordId"]}',NULL,'{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","steps":[{"stepIndex":0,"api":"data-api","operation":"update","layout":"Activity Report","fieldMappings":{"hours":"Hours","category":"Category","date":"Date_Act","ticketType":"Ticket Type","nonbillableTime":"Nonbillable_time"}}]}',NULL,NULL,'multi-step',true,1,true,NULL,0,'2026-05-21T04:22:54.190Z','2026-05-21T04:22:54.190Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Tool" ("id","serverId","name","description","category","inputSchema","outputSchema","handlerConfig","fmLayout","fmScript","fmMethod","isEnabled","version","isAiGenerated","testConfig","sortOrder","createdAt","updatedAt") VALUES ('cmpezj9hf000fv0qd7z217max','cmpe78bpf0000l704aera9ers','get_staff_rates','Retrieve billing rate information for a specific staff member, including their client-facing rate and internal KiBiz rate. Use this when preparing invoices, reviewing profitability, or validating billing configurations.','lookup','{"type":"object","properties":{"staffName":{"type":"string","description":"Name of the staff member to look up rates for"},"staffRole":{"type":"string","description":"Role to narrow down the search"}},"required":[]}',NULL,'{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","steps":[{"stepIndex":0,"api":"data-api","operation":"find","layout":"Staff List","fieldMappings":{"staffName":"StaffName","staffRole":"StaffRole"}}]}',NULL,NULL,'multi-step',true,1,true,NULL,0,'2026-05-21T04:23:00.291Z','2026-05-21T04:23:00.291Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Tool" ("id","serverId","name","description","category","inputSchema","outputSchema","handlerConfig","fmLayout","fmScript","fmMethod","isEnabled","version","isAiGenerated","testConfig","sortOrder","createdAt","updatedAt") VALUES ('cmpezjbmr000jv0qdpbbgd8j3','cmpe78bpf0000l704aera9ers','get_project_staff_hours','Look up a project by name or client code, then retrieve all activity hours logged against that project. Use this for a complete picture of team effort on a project, combining project metadata with time entry details.','multi-table','{"type":"object","properties":{"projectName":{"type":"string","description":"Name of the project to look up"},"clientCode":{"type":"string","description":"Client code associated with the project"},"dateFrom":{"type":"string","description":"Start date to filter activity entries"},"dateTo":{"type":"string","description":"End date to filter activity entries"},"limit":{"type":"number","description":"Max activity records to return, default 50"}},"required":[]}',NULL,'{"steps":[{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","stepIndex":0,"api":"data-api","operation":"find","layout":"Projects__Blank","fieldMappings":{"projectName":"Project_Name","clientCode":"Client Code"},"extractField":"ProjectID","useExtractedAs":"projectId"},{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","stepIndex":1,"api":"data-api","operation":"find","layout":"Activity Report","fieldMappings":{"projectId":"ProjectID","dateFrom":"Date_Act","dateTo":"Date_Act"}}],"connectionId":"cmpe6zbg10001lg04lz1pvsvg"}',NULL,NULL,'multi-step',true,1,true,NULL,0,'2026-05-21T04:23:03.075Z','2026-05-21T04:23:03.075Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Tool" ("id","serverId","name","description","category","inputSchema","outputSchema","handlerConfig","fmLayout","fmScript","fmMethod","isEnabled","version","isAiGenerated","testConfig","sortOrder","createdAt","updatedAt") VALUES ('cmpezjcef000nv0qdjkb38elp','cmpe78bpf0000l704aera9ers','get_staff_project_summary','Look up a staff member, then retrieve all their logged activity entries with total hours and non-billable breakdown. Use this when reviewing a staff member''s full time history across all projects, or for performance and billing summaries.','multi-table','{"type":"object","properties":{"staffName":{"type":"string","description":"Name of the staff member to summarize"},"email":{"type":"string","description":"Email of the staff member as an alternative lookup"},"dateFrom":{"type":"string","description":"Start date to filter activity entries"},"dateTo":{"type":"string","description":"End date to filter activity entries"},"limit":{"type":"number","description":"Max activity records to return, default 50"}},"required":[]}',NULL,'{"steps":[{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","stepIndex":0,"api":"data-api","operation":"find","layout":"Staff List","fieldMappings":{"staffName":"StaffName","email":"Email"},"extractField":"StaffID","useExtractedAs":"staffId"},{"connectionId":"cmpe6zbg10001lg04lz1pvsvg","stepIndex":1,"api":"data-api","operation":"find","layout":"Activity Report","fieldMappings":{"staffId":"StaffID","dateFrom":"Date_Act","dateTo":"Date_Act"}}],"connectionId":"cmpe6zbg10001lg04lz1pvsvg"}',NULL,NULL,'multi-step',true,1,true,NULL,0,'2026-05-21T04:23:04.071Z','2026-05-21T04:23:04.071Z') ON CONFLICT ("id") DO NOTHING;
